-- Sixth migration. Apply after the mural migration; no previous SQL is reapplied.
begin;
alter table public.member_profiles add column banner_path text
  check(public.valid_photo_path(banner_path,user_id,'banners'));

create or replace function public.identity_profile_json(p public.member_profiles) returns jsonb
language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('id',p.user_id,'username',p.username,'firstName',p.first_name,'lastName',p.last_name,
 'bio',p.bio,'avatarPath',p.avatar_path,'bannerPath',p.banner_path,'tone',p.tone,'tags',p.tags,'discoverable',p.discoverable,
 'usernameChangedAt',p.username_changed_at,'usernameAvailableAt',p.username_changed_at+interval '30 days','createdAt',p.created_at);
$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('profile-banners','profile-banners',false,2097152,array['image/jpeg']);
create function public.profile_banner_readable(path text) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.member_profiles p where p.banner_path=path and public.profile_is_visible(p.user_id));
$$;
revoke all on function public.profile_banner_readable(text) from public,anon;
grant execute on function public.profile_banner_readable(text) to authenticated;
create policy profile_banner_insert on storage.objects for insert to authenticated with check(
 bucket_id='profile-banners' and public.closet_session_allowed() and name is not null and public.valid_photo_path(name,auth.uid(),'banners'));
create policy profile_banner_read on storage.objects for select to authenticated using(
 bucket_id='profile-banners' and (public.profile_banner_readable(name) or
 (public.closet_session_allowed() and name is not null and public.valid_photo_path(name,auth.uid(),'banners'))));
create policy profile_banner_delete on storage.objects for delete to authenticated using(
 bucket_id='profile-banners' and public.closet_session_allowed() and name is not null and public.valid_photo_path(name,auth.uid(),'banners'));
create function public.profile_set_banner(p_path text) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 perform public.require_closet_session();
 if not public.valid_photo_path(p_path,auth.uid(),'banners') then raise exception 'INVALID_BANNER' using errcode='22023';end if;
 if p_path is not null and not exists(select 1 from storage.objects where bucket_id='profile-banners' and name=p_path) then
  raise exception 'BANNER_NOT_UPLOADED' using errcode='22023';end if;
 update public.member_profiles set banner_path=p_path where user_id=auth.uid();
 if not found then raise exception 'PROFILE_REQUIRED' using errcode='22023';end if;
 return public.identity_account();
end;
$$;
revoke all on function public.profile_set_banner(text) from public,anon;
grant execute on function public.profile_set_banner(text) to authenticated;
create table public.social_notebook_entries (
 user_id uuid not null references public.member_profiles(user_id) on delete cascade,
 publication_id uuid not null references public.social_publications(id) on delete cascade,
 note text not null check(length(note)<=1200), updated_at timestamptz not null default now(),
 primary key(user_id,publication_id)
);
alter table public.social_notebook_entries enable row level security;
revoke all on public.social_notebook_entries from public,anon,authenticated;
create function public.social_notebook(p_action jsonb) returns text
language plpgsql security definer set search_path='' as $$
declare target uuid:=(p_action->>'id')::uuid; value text; p public.social_publications;
begin
 perform public.require_closet_session();
 select * into p from public.social_publications where id=target;
 if p.id is null or not public.social_visible(p) then raise exception 'PUBLICATION_UNAVAILABLE' using errcode='42501';end if;
 if p_action->>'kind'='save' then
  if jsonb_typeof(p_action->'note') is distinct from 'string' or length(p_action->>'note')>1200 then
   raise exception 'INVALID_NOTE' using errcode='22023';end if;
  value:=btrim(p_action->>'note');
  if value='' then delete from public.social_notebook_entries where user_id=auth.uid() and publication_id=target;
  else insert into public.social_notebook_entries(user_id,publication_id,note) values(auth.uid(),target,value)
  on conflict(user_id,publication_id) do update set note=excluded.note,updated_at=now();end if;
 elsif p_action->>'kind' is distinct from 'get' then raise exception 'INVALID_ACTION' using errcode='22023';end if;
 return coalesce((select note from public.social_notebook_entries where user_id=auth.uid() and publication_id=target),'');
end;
$$;
revoke all on function public.social_notebook(jsonb) from public,anon;
grant execute on function public.social_notebook(jsonb) to authenticated;

-- Curated catalog with documented photographic provenance. Earlier records are retained, but not promoted until their attribution is verified.
alter table public.social_publications add column curation_approved boolean not null default false;
create or replace function public.social_visible(p public.social_publications) returns boolean language sql stable security definer set search_path='' as $$ select public.closet_session_allowed() and ((p.curated and p.curation_approved) or (not p.curated and public.profile_is_visible(p.author_id))); $$;
